// Generated from seo-data.json — do not edit manually
// Field mapping: STATE_NAME→name, STATE_ABBR→abbreviation, etc.

export interface StateExamInfo {
  passingScore: number;
  passRate: string;
  examFee: string;
  examProvider: string;
  examProviderUrl: string;
  examBookingUrl: string;
  retakeWaitingPeriod: string;
  retakeLimitInfo: string;
  examResultsTiming: string;
  examSchedulingInfo: string;
}

export interface CoursePricing {
  hours: number | string; // string for "Not Required" states
  price: string;
  totalCost: string;
  completionTime: string;
}

export interface PracticeExams {
  lifeUrl: string;
  healthUrl: string;
  combinedUrl: string;
  price: string;
}

export interface StateNoticeEntry {
  kind: "alert" | "update" | "tip";
  title: string;
  body: string;
  link?: { href: string; text: string; external?: boolean };
}

export interface CEComplianceData {
  lateFee: string;
  gracePeriod: string;
  reinstatementFee: string;
  reinstatementWindow: string;
  carryForward: string;
  lapseConsequence: string;
}

export interface CEInfo {
  totalHours: number;
  renewalPeriod: string;
  ethicsHours: number;
  requirementsUrl: string;
  packagePrice: string;
  ethicsCoursePrice: string;
  individualCoursePrice: string;
  completionTime: string;
  compliance?: CEComplianceData;
}

export interface StateData {
  name: string;
  abbreviation: string;
  slug: string;

  // DOI info
  doiName: string;
  doiAbbr: string;
  doiUrl: string;
  doiPhone: string;
  doiEmail: string;
  regulatoryBody: string;

  // Licensing info
  agentLicensingUrl: string;
  licenseApplicationPortal: string;
  licenseDuration: string;
  minAge: number;
  residencyRequirement: string;
  backgroundRequirement: string;
  fingerprintRequirement: string;
  applicationProcess: string;
  applicationFee: string;
  backgroundCheckCost: string;
  totalCostRange: string;
  applicationProcessingTime: string;
  licenseIssueTime: string;
  totalLicensingTime: string;

  // Provider info
  providerNumber: string;

  // Exam info
  examInfo: StateExamInfo;
  noCombinedExam: boolean;
  applicationBeforeExam: boolean;

  // Course pricing
  prelicensing: {
    life: CoursePricing;
    health: CoursePricing;
    lifeAndHealth: CoursePricing;
  };
  ce: CEInfo;
  practiceExams?: PracticeExams;
  specialNotices?: StateNoticeEntry[];

  // Income/career data
  studentsCount: string;
  avgIncome: string;
  jobGrowth: string;
  firstYearIncome: string;
  firstYearIncomeHigh: string;
  experiencedIncome: string;
  experiencedIncomeHigh: string;
  topProducerIncome: string;

  // Content helpers
  testimonial1Name: string;
  testimonial2Name: string;
  city1: string;
  city2: string;
  timezone: string;

  // Additional info
  reciprocityInfo: string;
  sponsorshipRequirement: string;
  courseWeeks: string;
  courseAccessDays: string;
  combinedSavings: string;
  combinedVsSinglePercent: string;

  // Legal citations
  citations: {
    insuranceCode: string;        // STATE_INSURANCE_CODE
    insuranceCodeFull: string;    // STATE_INSURANCE_CODE_FULL_REFERENCE
    prelicenseCode: string;       // PRE_LICENSE_CODE
    ceRequirementsCode: string;   // CE_REQUIREMENTS_CODE
    ceEthicsCode: string;         // CE_ETHICS_CODE
    providerRegulation: string;   // PROVIDER_REGULATION
    adminCodeName: string;        // STATE_ADMIN_CODE_NAME
    adminCodeRef: string;         // STATE_ADMIN_CODE_REFERENCE
    adminCodeUrl: string;         // STATE_ADMIN_CODE_URL
    statutesUrl: string;          // STATE_STATUTES_URL
    ageCitation: string;          // AGE_CITATION
    educationCitation: string;    // EDUCATION_CITATION
    examCitation: string;         // EXAM_CITATION
    backgroundCitation: string;   // BACKGROUND_CITATION
    fingerprintCitation: string;  // FINGERPRINT_CITATION
    applicationCitation: string;  // APPLICATION_CITATION
  };
  certificateValidity: string;
  paymentPlanInfo: string;

  // SEO uniqueness fields
  providerApprovalNumber: string;
  lastVerified: string;
  realPassRate: number | null;
  marketGrowthRate: number | null;
  renewalDeadline: string;
  fingerprintingNotes: string;
  nameMatchWarning: string;
  specialTrainingRequirements: {
    ltc: string | null;
    nfip: string | null;
    annuity: string | null;
    other: string | null;
  };
  stateSpecificIntro: string;
  stateSpecificFAQ: {
    question: string;
    answer: string;
  };
  stateTestimonial: {
    quote: string;
    name: string;
    title: string;
  };
}

